INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,0,'见群龙无首，吉。','用九：群龙出现而不以首领自居。象征刚健而能不争不亢，刚中带柔之道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,1,'潜龙，勿用。','龙潜于渊，时机未至。象征才德尚在积蓄阶段，古人认为此时宜潜藏修养而不宜轻动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,2,'见龙在田，利见大人。','龙现于田野，崭露头角。象征才德开始显现于世，利于结识有助益的人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,3,'君子终日乾乾，夕惕若，厉无咎。','整日勤勉不懈，入夜仍心存警惕。象征身处多忧之位，唯戒慎勤勉方能不出差错。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,4,'或跃在渊，无咎。','或跃起或退处于渊，进退皆有余地。象征面临抉择关口，审时度势而后动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,5,'飞龙在天，利见大人。','龙飞于天，大展其用。象征事物达于鼎盛得位之时，德位相称，众望所归。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(1,6,'亢龙有悔。','龙飞过高，将有所悔。象征盛极而衰之理，戒在知进而不知退、知存而不知亡。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,0,'利永贞。','用六：利于永远守持正固。象征柔顺之德贵在恒久不变。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,1,'履霜，坚冰至。','踩到秋霜，便知坚冰将至。象征见微知著，事物的变化自细微处逐渐累积。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,2,'直，方，大，不习无不利。','平直、方正、广大，不必修习也无所不利。象征顺应天然本性而行，不假造作。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,3,'含章可贞。 或从王事，无成有终。','内含章美而能守正，或辅佐王事，不居其功而有善终。象征敛藏才华、功成不居。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,4,'括囊﹔无咎，无誉。','扎紧口袋，无过失也无称誉。象征谨言慎行、敛藏自守以避嫌疑之时。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,5,'黄裳，元吉。','黄色下裳，大为吉祥。黄为中色、裳为下饰，象征居尊位而守中谦下之德。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(2,6,'龙战于野，其血玄黄。','龙战于郊野，其血玄黄。象征阴盛至极而与阳相争，两败俱伤之象。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,1,'磐桓﹔利居贞，利建侯。','徘徊难进之时，利于安居守正，利于建侯立辅。象征创始之初先立根基。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,2,'屯如邅如，乘马班如。 匪寇婚媾，女子贞不字，十年乃字。','进退迍邅，乘马盘旋。并非寇仇而是求婚配。女子守正不许嫁，十年方嫁。象征时机未熟，宁可久待。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,3,'既鹿无虞，惟入于林中，君子几不如舍，往吝。','逐鹿而无虞人引导，只会迷入林中。君子见机而舍弃，强往则有憾惜。象征无援无备则不可贸然行事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,4,'乘马班如，求婚媾，无不利。','乘马盘旋，前往求婚配，往则吉而无所不利。象征条件已备，把握时机则有善果。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,5,'屯其膏，小贞吉，大贞凶。','恩泽屯积难施。小事守正尚可，大事固执则凶。象征居位而施展受阻，宜从小处渐进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(3,6,'乘马班如，泣血涟如。','乘马盘旋不前，泣血涟涟。象征困境至极而无所适从之象。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,1,'发蒙，利用刑人，用说桎梏，以往吝。','启发蒙昧，利于树立规范，去其桎梏；一味放任则有憾惜。象征启蒙之初须立规矩。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,2,'包蒙吉，纳妇吉，子克家。','包容蒙昧者，吉；纳娶妻室，吉；子能承家。象征宽容化育、刚柔相济之道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,3,'勿用娶女，见金夫，不有躬，无攸利。','不宜娶这样的女子：见有金之夫便失其身，无所利。象征失其操守者不可与共事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,4,'困蒙，吝。','困于蒙昧而远离贤明，有憾惜。象征自我封闭、不亲师友则难以开悟。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,5,'童蒙，吉。','童子之蒙，吉。象征虚心若孩童、乐于受教，是启蒙最好的状态。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(4,6,'击蒙，不利为寇，利御寇。','以猛击治蒙。不利于为寇，利于御寇。象征严教当以防御纠偏为度，不可过暴。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,1,'需于郊。 利用恒，无咎。','在郊野等待，利于恒常自处，无过失。象征远离险地、安处待时。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,2,'需于沙。 小有言，终吉。','在沙滩等待，稍有言语之伤，终得吉。象征渐近于险，受些非议而无大碍。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,3,'需于泥，致寇至。','在泥泞中等待，招致寇至。象征逼近险境，自取其困，须敬慎方免败。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,4,'需于血，出自穴。','在血泊中等待，从陷穴中脱出。象征已入险境，顺势而退方能脱离。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,5,'需于酒食，贞吉。','在酒食宴乐中等待，守正则吉。象征居中得位，从容自养以待时变。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(5,6,'入于穴，有不速之客三人来，敬之终吉。','落入陷穴，有不速之客三人来，敬重他们终得吉。象征险极而变，以敬待人可化险为安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,1,'不永所事，小有言，终吉。','不久缠于争端，稍有言语之伤，终得吉。象征讼事宜早息，不使滋长。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,2,'不克讼，归而逋，其邑人三百户，无眚。','争讼不胜，归而逃避，邑人三百户因而无灾。象征力不敌则退避自保，祸不及众。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,3,'食旧德，贞厉，终吉，或从王事，无成。','安享旧日俸禄，守正防危，终吉；或从王事，不居其功。象征不贪进取、守分免争。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,4,'不克讼，复自命，渝安贞，吉。','争讼不胜，回心转意，改变初衷而安于正道，吉。象征知错而返，安命守正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,5,'讼元吉。','决断争讼，大为吉祥。象征居中得正、公正裁断，讼事得平。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(6,6,'或锡之鞶带，终朝三褫之。','或受赐官服大带，一日之内三次被剥夺。象征以讼取胜所得，终难长保。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,1,'师出以律，否臧凶。','出师须以纪律为先，纪律不良则凶。象征行事之初必正其规。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,2,'在师中，吉无咎，王三锡命。','身在军中而得中道，吉而无咎，王三次锡命嘉奖。象征将帅刚中得位，上下信任。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,3,'师或舆尸，凶。','军中或有舆尸而归之败，凶。象征用人不当、号令不一则致覆败。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,4,'师左次，无咎。','军队后撤驻守，无咎。象征量力而退、暂避其锋并非过失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,5,'田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。','田中有禽，利于声讨捕获，无咎。长子帅师，弟子舆尸，守正亦凶。象征出师有名且任将必专。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(7,6,'大君有命，开国承家，小人勿用。','大君颁布成命，开国承家，小人不可任用。象征论功行赏须明辨贤否。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,1,'有孚比之，无咎。 有孚盈缶，终来有他，吉。','心怀诚信去亲附，无咎。诚信充盈如满缶，终有意外之吉。象征亲比以诚为本。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,2,'比之自内，贞吉。','发自内心地亲附，守正则吉。象征由衷相亲而非攀附。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,3,'比之匪人。','亲附于不当亲附之人。象征所托非人，徒增伤悲。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,4,'外比之，贞吉。','在外亲附贤者，守正则吉。象征择善而从，向上亲贤。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,5,'显比，王用三驱，失前禽。 邑人不戒，吉。','光明正大的亲附。如王者三面驱围、网开一面，邑人不相警惧，吉。象征宽仁不迫、来去自愿的王道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(8,6,'比之无首，凶。','亲附而无首领可从，凶。象征亲比失其归宿，终无所成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,1,'复自道，何其咎，吉。','返回自己的正道，有什么过失呢，吉。象征受阻而能复归本位。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,2,'牵复，吉。','被牵连而一同返回，吉。象征与同志携手共退，不失其中。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,3,'舆说辐，夫妻反目。','车辐脱落，夫妻反目。象征强行前进则受制，内部生隙。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,4,'有孚，血去惕出，无咎。','心怀诚信，忧惧远去血伤，无咎。象征以诚信处惧，可免伤害。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,5,'有孚挛如，富以其邻。','有诚信而牵系群邻，以富与邻共。象征居尊以诚，与人同利。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(9,6,'既雨既处，尚德载，妇贞厉。 月几望，君子征凶。','既已落雨既已安处，尚德积满。妇人守正防危，月几望，君子征进则凶。象征畜聚已极，宜静不宜动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,1,'素履，往无咎。','以素朴之心前行，无咎。象征安于本分、不慕虚饰地践行其志。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,2,'履道坦坦，幽人贞吉。','行走在平坦大道上，幽静安恬者守正则吉。象征恬淡自守、不陷纷扰。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,3,'眇能视，跛能履，履虎尾，咥人，凶。 武人为于大君。','目眇而强视，足跛而强行，踩虎尾被咬，凶；武人逞强于大君。象征才不胜任而刚愎冒进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,4,'履虎尾，愬愬终吉。','踩到虎尾，恐惧戒惕，终得吉。象征临危知惧、敬慎而行可济。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,5,'夬履，贞厉。','果决地践行，守正防危。象征居尊位而独断专行，虽正亦须自警。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(10,6,'视履考祥，其旋元吉。','回顾所行之路，考察祸福征兆，圆满则大吉。象征行事善始善终，省察而后得福。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,1,'拔茅茹，以其夤，征吉。','拔起茅草，根系相连，与同类共进，征往则吉。象征贤者引类而进，其道方亨。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,2,'包荒，用冯河，不遐遗，朋亡，得尚于中行。','包容广大，徒步涉河之勇，不遗弃远人，不结朋党，得行中道。象征泰世用人宏大公允。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,3,'无平不陂，无往不复，艰贞无咎。 勿恤其孚，于食有福。','没有只平不陂的地，没有只往不返的事。艰贞无咎，不必忧恤，于食有福。象征泰中藏否，居安思危。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,4,'翩翩不富，以其邻，不戒以孚。','翩然下降，不以富自恃而与邻相亲，不待告诫而心存诚信。象征上下交孚、虚己待人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,5,'帝乙归妹，以祉元吉。','帝乙嫁妹，以此得福，大为吉祥。象征尊者谦降、上下交好之美。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(11,6,'城复于隍，勿用师。 自邑告命，贞吝。','城墙倾覆于干涸的护城壕。勿用兴师，自邑传告政令，守正亦有憾。象征泰极而否，大势难以强挽。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,1,'拔茅茹，以其夤，贞吉亨。','拔起茅草根系相连，与同类共守，贞吉而亨。象征闭塞之初，贤者连类自守不进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,2,'包承。 小人吉，大人否亨。','包容承顺，小人吉；大人安于否塞，亨。象征君子不与小人混同，否中自亨。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,3,'包羞。','包藏羞愧。象征居位不当、所行可耻而终自知羞。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,4,'有命无咎，畴离祉。','奉有天命而行，无咎，同类皆依附得福。象征转否之机已现，奉正道而动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,5,'休否，大人吉。 其亡其亡，系于苞桑。','休止否塞，大人之吉。系于苞桑，其亡其亡，时刻自警。象征居安思危，方能固结不拔。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(12,6,'倾否，先否后喜。','倾覆否塞。先有否塞后有喜悦。象征否极泰来，闭塞终被冲破。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,1,'同人于门，无咎。','出门便与人和同，无咎。象征胸怀开阔、不分亲疏地与人交往。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,2,'同人于宗，吝。','只在宗族内和同，有憾惜。象征结党于私、所同者狭。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,3,'伏戎于莽，升其高陵，三岁不兴。','伏兵于草莽，登高观望，三年不敢兴兵。象征心怀私忌则同道难成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,4,'乘其墉，弗克攻，吉。','乘上城垣却不进攻，吉。象征知争之不义而能自反。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,5,'同人，先号啕而后笑。 大师克相遇。','和同于人，先号啕而后欢笑，大军会合相遇。象征至诚相感，历经阻隔终得会合。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(13,6,'同人于郊，无悔。','在郊外与人和同，无所悔。象征远处无争之地，志虽未大行而心安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,1,'无交害，匪咎，艰则无咎。','不与祸害相涉，自非有咎；艰苦自守则无咎。象征大有之初，不骄不纵。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,2,'大车以载，有攸往，无咎。','大车载物，有所前往，无咎。象征才力厚实，足以任重行远。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,3,'公用亨于天子，小人弗克。','公侯以丰有献享天子，小人则不能胜任。象征富而能公，器小者反受其累。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,4,'匪其彭，无咎。','不自我膨胀盛大，无咎。象征处近君之位，敛抑自损以避盈满。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,5,'厥孚交如，威如﹔吉。','以诚信交接上下，威严自显，吉。象征柔中居尊，诚信而有威仪。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(14,6,'自天佑之，吉无不利。','得自上天的护佑，吉而无所不利。象征顺天应人、尚贤崇善之极致。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,1,'谦谦君子，用涉大川，吉。','谦而又谦的君子，可涉越大川，吉。象征以至谦之德涉险济难。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,2,'六二，鸣谦，贞吉。','谦德发于声闻，守正则吉。象征谦出于中心，自然形于外。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,3,'九三，劳谦，君子有终，吉。','勤劳而谦虚的君子，有好的结局，吉。象征有大功而不自伐，万民信服。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,4,'无不利，㧑谦。','无所不利，发挥谦德。象征居上下之间，动静皆以谦行之。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,5,'不富，以其邻，利用侵伐，无不利。','不以富自恃而亲其邻，利于以此征伐不服，无所不利。象征谦非懦弱，柔中有为。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(15,6,'鸣谦，利用行师，征邑国。','谦德彰闻于外，利于兴师征治封邑之内。象征谦极而志未得，先正己内。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,1,'鸣豫，凶。','自鸣得意地欢乐，凶。象征恃宠而骄、得意忘形则志穷致凶。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,2,'介于石，不终日，贞吉。','耿介如石，不终日享乐，守正则吉。象征中正自守，见机之明不待终日。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,3,'盱豫，悔。 迟有悔。','仰人鼻息地求乐，有悔；迟疑不改则更有悔。象征媚上偷安，悔之又悔。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,4,'由豫，大有得。勿疑。 朋盍簪。','由己而出的欢乐，大有所得；勿疑，朋友合聚如簪束发。象征以诚聚众，乐由正出。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,5,'贞疾，恒不死。','守正而抱疾，常久而不死。象征沉溺安乐如负痼疾，赖中位而存。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(16,6,'冥豫，成有渝，无咎。','昏冥于逸乐，事已成形，能改变则无咎。象征乐极生昏，迷途知返犹未为晚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,1,'官有渝，贞吉。 出门交有功。','主见有所变通，守正则吉；出门与人交往便有功。象征不固执己见，从善如流。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,2,'系小子，失丈夫。','系恋小子而失去丈夫。象征所随者近小失大，不能兼得。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,3,'系丈夫，失小子， 随有求得，利居贞。','系随丈夫而舍去小子，随之有求皆得，利于安居守正。象征弃下从上、舍小取大。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,4,'随有获，贞凶，有孚在道，以明，何咎。','随从而有所获，守正亦有凶；以诚信居正道而申明之，何咎之有。象征获众之时尤须诚明自处。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,5,'孚于嘉，吉。','以诚信嘉善，吉。象征居中得正，所随者善，上下交孚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(17,6,'拘系之，乃从维之。 王用亨于西山。','拘系而又捆绑相随，王以此亨祭于西山。象征随道之极，固结不解。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,1,'干父之蛊，有子考无咎，厉终吉。','匡正父辈的积弊，有这样的儿子，先辈可免咎；虽危而终吉。象征承继者善补前失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,2,'干母之蛊，不可贞。','匡正母辈的积弊，不可固执强正。象征以柔济柔，矫弊宜得中道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,3,'干父之蛊，小有悔，无大咎。','匡正父辈积弊，稍有悔恨，无大咎。象征矫枉略过，志在救弊则瑕不掩瑜。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,4,'裕父之蛊，往见吝。','宽缓地对待父辈积弊，前往则见憾惜。象征姑息因循，弊将日深。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,5,'干父之蛊，用誉。','匡正父辈的积弊，承之以美誉。象征以德继业，化弊为誉。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(18,6,'不事王侯，高尚其事。','不事奉王侯，高尚自己的志节。象征事外之贤，洁身自守，其志可则。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,1,'咸临，贞吉。','以感应临下，守正则吉。象征上下感而相应，行之以正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,2,'咸临，吉无不利。','以感应临下，吉而无所不利。象征刚中之德感而能动，不待命令而顺。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,3,'甘临，无攸利。 既忧之，无咎。','以甘悦之言临下，无所利；既已忧惧自改，则无咎。象征徒以甘言悦人不可久，改之则善。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,4,'至临，无咎。','亲身切至地临下，无咎。象征居位得当、亲贤任能。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,5,'知临，大君之宜，吉。','以明智临下，大君之所宜，吉。象征不必事事躬亲，知人善任即大君之智。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(19,6,'敦临，吉无咎。','以敦厚临下，吉而无咎。象征临道之成，归于笃实宽厚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,1,'童观，小人无咎，君子吝。','如孩童之观，浅近无识。小人无咎，君子则有憾。象征所见浅薄，居下尚可，任事则不足。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,2,'窥观，利女贞。','从门缝中窥观，利于女子之贞。象征所见狭隘，仅宜安于内分。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,3,'观我生，进退。','观察自我的进退出处。象征省察己身、审时度势而未失其道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,4,'观国之光，利用宾于王。','观仰国家的光辉，利于做君王的宾客。象征亲见盛德大业，可出而效用。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,5,'观我生，君子无咎。','观省自身，君子则无咎。象征居尊位者观民风以省己政。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(20,6,'观其生，君子无咎。','为天下所观仰，君子则无咎。象征身处众目所瞩，志在自省而不敢自安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,1,'履校灭趾，无咎。','戴上脚枷，遮没脚趾，无咎。象征惩之于小、戒之于初，免入大恶。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,2,'噬肤灭鼻，无咎。','咬啮皮肉，深没其鼻，无咎。象征施刑于顺服者，虽深无害。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,3,'噬腊肉，遇毒﹔小吝，无咎。','咬腊肉而遇毒味，稍有憾惜，无咎。象征治人而人不服，位不当则生小怨。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,4,'噬乾胏，得金矢，利艰贞，吉。','咬带骨干肉，得金箭。利于艰苦守正，吉。象征执法遇坚，以刚直自持乃克。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,5,'噬乾肉，得黄金，贞厉，无咎。','咬干肉而得黄金。守正防危，无咎。象征柔中执法，得刚明之助而自警。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(21,6,'何校灭耳，凶。','肩负重枷，遮没耳朵，凶。象征恶积罪大、怙恶不悛，刑之极致。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,1,'贲其趾，舍车而徒。','文饰其足，舍车而徒步。象征居下守义，安步当车而不苟乘。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,2,'贲其须。','文饰其须。须附于颐，象征文不虚生，附丽于实而动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,3,'贲如濡如，永贞吉。','文饰润泽，永守正固则吉。象征沉浸于文饰之美，须以恒正自守。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,4,'贲如皤如，白马翰如，匪寇婚媾。','素白如飞，白马翰如奔驰；非为寇仇乃求婚配。象征弃华求素，诚意终达。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,5,'贲于丘园，束帛戋戋，吝，终吉。','文饰于丘园，束帛微薄，有吝惜之憾，终吉。象征崇尚俭质、敦本务实。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(22,6,'白贲，无咎。','以素白为饰，无咎。象征文饰之极复归于质朴，返本则无失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,1,'剥床以足，蔑贞凶。','剥蚀床足，毁灭正道，凶。象征侵蚀自下而始，根基先坏。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,2,'剥床以辨，蔑贞凶。','剥蚀床身，毁灭正道，凶。象征剥势渐进，祸已及身而无与之应。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,3,'剥之，无咎。','身处剥世而独无咎。象征虽在群阴之中，独应于阳、不同流合污。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,4,'剥床以肤，凶。','剥蚀床面而切及肌肤，凶。象征灾祸切身，剥极之危。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,5,'贯鱼，以宫人宠，无不利。','贯鱼而进，如宫人依次受宠，无所不利。象征群阴有序听命于阳，转祸为顺。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(23,6,'硕果不食，君子得舆，小人剥庐。','硕大果实未被食尽。君子得舆，小人剥庐。象征阳刚不可尽灭，硕果仅存而生机复萌。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,1,'不复远，无只悔，元吉。','迷途未远即复归，无悔恨之事，大为吉祥。象征改过于初萌，修身之要。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,2,'休复，吉。','美好的复归，吉。象征亲近仁者、见善而从。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,3,'频复，厉无咎。','屡失屡复，虽危而无咎。象征改过不坚而能屡返，终胜不返。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,4,'中行独复。','行于群阴之中而独自复归正道。象征从道而行，不徇众流。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,5,'敦复，无悔。','敦厚笃实地复归，无悔。象征以厚德自考自成，复之笃实者。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(24,6,'迷复，凶，有灾眚。用行师，终有大败，以其国君凶﹔至于十年不克征。','迷而不复，凶，有灾祸。用以行师终有大败，殃及国君，十年不能振作。象征执迷不返，反君道之极。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,1,'无妄，往吉。','不妄为而前往，吉。象征以诚正之心而动，所往得志。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,2,'不耕获，不菑畬，则利有攸往。','不为获而耕，不为收而垦，则利有攸往。象征不计利而为所当为。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,3,'无妄之灾，或系之牛，行人之得，邑人之灾。','无妄之灾：或有系牛于路，行人牵去，邑人遭殃。象征无故之灾，非行有不正所致。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,4,'可贞，无咎。','可以守持正固，无咎。象征固守其常、不为外物所动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,5,'无妄之疾，勿药有喜。','无妄而得疾，勿药自愈而有喜。象征非己之过所致之患，不治自复。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(25,6,'无妄，行有眚，无攸利。','无妄之行至极，再往则有灾，无所利。象征时穷势尽，虽正亦不可妄进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,1,'有厉利已。','有危险，利于止而不进。象征受畜止之时，量势自止则免灾。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,2,'舆说辐。','车舆脱去轮輹。象征自止其行，不冒进相抗，中道自守。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,3,'良马逐，利艰贞。 曰闲舆卫，利有攸往。','良马驰逐，利于艰难中守正。日日练习驾车与防卫，则利有攸往。象征畜极而通，犹须戒备不懈。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,4,'童牛之牿，元吉。','加横木于童牛之角，大为吉祥。象征止恶于未萌，禁微则易。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,5,'豮豕之牙，吉。','去势之猪的牙，吉。象征制其根本而不与其锋角力。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(26,6,'何天之衢，亨。','何等通达的天衢大道，亨通。象征畜极而散，贤路大开，其道大行。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,1,'舍尔灵龟，观我朵颐，凶。','舍弃自己的灵龟之明，观我而垂涎欲食，凶。象征弃己之贵而羡人之食。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,2,'颠颐，拂经，与丘颐，征凶。','颠倒向下求养，又违常理求养于高丘，征往则凶。象征求养失其正道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,3,'拂颐，贞凶，十年勿用，无攸利。','违背颐养之正，守此则凶，十年勿用，无所利。象征以邪道自养，终不可行。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,4,'颠颐吉，虎视眈眈，其欲逐逐，无咎。','颠倒求养于下而吉。虎视眈眈，其欲逐逐，无咎。象征居上养贤以及民，专诚不懈。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,5,'拂经，居贞吉，不可涉大川。','违常而居，安守正固则吉，不可涉越大川。象征赖人之养以养人，宜静不宜涉险。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(27,6,'由颐，厉吉，利涉大川。','天下由之得养，任重而危，终吉。利于涉越大川。象征以养天下为己任，危而后安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,1,'藉用白茅，无咎。','以白茅垫物而祭，无咎。象征处非常之始，敬慎之至。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,2,'枯杨生稊，老夫得其女妻，无不利。','枯杨生出新芽，老夫得少妻，无所不利。象征过而能济，衰中复振。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,3,'栋桡，凶。','栋梁弯折，凶。象征刚强自任而不胜其重，无辅而败。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,4,'栋隆，吉﹔有它吝。','栋梁隆起，吉；若另有他属则有憾惜。象征得辅而任重，济弱扶倾而不可有私。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,5,'枯杨生华，老妇得士夫，无咎无誉。','枯杨开花，老妇得少夫，无咎无誉。象征过极之济，徒有其表而不能久。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(28,6,'过涉灭顶，凶，无咎。','涉水过深没顶，凶，但无咎责。象征杀身济难、义无可咎之极境。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,1,'习坎，入于坎窞，凶。','重险之下又入险穴，凶。象征习于险恶而愈陷愈深，失道致凶。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,2,'坎有险，求小得。','身处险中，求小有所得。象征未能出险之时，先求自全于中。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,3,'来之坎坎，险且枕，入于坎窞，勿用。','来去皆险，险且枕伏于前，入于险穴，勿用。象征进退皆险，妄动则愈陷。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,4,'樽酒簋贰，用缶，纳约自牖，终无咎。','一樽酒、两簋食，用瓦缶盛之，从窗牖结纳，终无咎。象征险难之时以质诚相交。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,5,'坎不盈，只既平，无咎。','险穴未盈满，将平复，无咎。象征险将出而未出，守中待平。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(29,6,'系用徽𬙊，置于丛棘，三岁不得，凶。','被绳索捆缚，置于荆棘丛中，三年不得解，凶。象征陷险至深，失道之久。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,1,'履错然，敬之无咎。','步履交错纷杂，心存敬慎，无咎。象征附丽之初，慎其所行所附。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,2,'黄离，元吉。','附丽于黄色中道，大为吉祥。象征得中守正，文明之盛。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,3,'日昃之离，不鼓缶而歌，则大耋之嗟，凶。','日已西斜之附丽。不鼓缶而歌，则有迟暮之嗟，凶。象征盛极将衰而不知达观自处。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,4,'突如其来如，焚如，死如，弃如。','突然而来，焚如、死如、弃如。象征暴烈躁进，无所容于人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,5,'出涕沱若，戚嗟若，吉。','泪流滂沱，忧戚嗟叹，吉。象征居尊履危而知忧惧，忧能转吉。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(30,6,'王用出征，有嘉折首，获其匪丑，无咎。','王者用以出征，有嘉功，斩首恶而不问胁从，无咎。象征明照之极，除恶务本而不滥。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,1,'咸其拇。','感应于脚拇指。象征感之尚浅，志动而未行。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,2,'咸其腓，凶，居吉。','感应于小腿肚，凶；安居则吉。象征感而躁动则失，静处待时则安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,3,'咸其股，执其随，往吝。','感应于大腿，执意追随他人，前往则有憾。象征不能自主、随人而动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,4,'贞吉悔亡，憧憧往来，朋从尔思。','守正则吉，悔恨消亡。心思往来不定，朋友才从你的思念。象征感贵以诚，私系则狭。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,5,'咸其脢，无悔。','感应于背脊，无悔。象征感而不为私欲所动，所感者末则无深功亦无悔。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(31,6,'咸其辅，颊，舌。','感应于口舌。象征徒以言语动人，感之至浅者。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,1,'浚恒，贞凶，无攸利。','求恒太深太急，守此则凶，无所利。象征始求深固，不知渐进之道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,2,'悔亡。','悔恨消亡。象征以刚居中，久于中道则悔自亡。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,3,'不恒其德，或承之羞，贞吝。','不能恒守其德，或承受羞辱；守此则有憾。象征德无恒守，无所容身。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,4,'田无禽。','田猎而无禽获。象征久居其位而非其所，虽劳而终无所成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,5,'恒其德，贞，妇人吉，夫子凶。','恒守其德，守正。妇人吉，夫子凶。象征从一而终宜于妇道，丈夫制义则不可从妇。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(32,6,'振恒，凶。','以振动为恒，凶。象征居上而躁动不安，恒道尽失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,1,'遁尾，厉，勿用有攸往。','退避而落在末尾，有危险，勿有所往。象征退之不及，居后近险，静止为宜。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,2,'执之用黄牛之革，莫之胜说。','用黄牛之革执系，无人能解。象征中正自固，其志坚不可夺。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,3,'系遁，有疾厉，畜臣妾吉。','心有系恋的退避，如有疾患般危困；蓄养臣妾尚可。象征恋恋不舍则退而不净，不堪大事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,4,'好遁君子吉，小人否。','心虽有好而能退避，君子吉，小人则否。象征能克己之私而决然引退。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,5,'嘉遁，贞吉。','嘉美的退避，守正则吉。象征时止则止，进退合于中正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(33,6,'肥遁，无不利。','从容宽裕的退避，无所不利。象征超然远引、无所疑滞，退之最优者。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,1,'壮于趾，征凶，有孚。','强壮在脚趾，征往有凶，应有诚信自守。象征居下而恃壮躁进，必致困穷。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,2,'贞吉。','守正则吉。象征以刚处柔而得中道，强盛之时不恃其壮。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,3,'小人用壮，君子用罔，贞厉。 羝羊触藩，羸其角。','小人恃用其壮，君子用罔不顾；守此则危。如公羊触藩，角被挂住。象征恃力妄进，进退两难。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,4,'贞吉悔亡，藩决不羸，壮于大舆之輹。','守正则吉，悔恨消亡。藩篱冲开而角不被缠，强壮如大车之輹。象征以盛壮之力开通前路而不失正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,5,'丧羊于易，无悔。','在田界间失去羊，无悔。象征壮势已去，以柔处之则无所悔。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(34,6,'羝羊触藩，不能退，不能遂，无攸利，艰则吉。','公羊触藩，不能退也不能进，无所利；知艰自处则吉。象征壮极成困，知难自省方有转机。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,1,'晋如，摧如，贞吉。 罔孚，裕无咎。','上进受阻摧折，守正则吉。未获信任，宽裕自处则无咎。象征进之初遭抑，不失其正而能宽。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,2,'晋如，愁如，贞吉。 受兹介福，于其王母。','上进而忧愁，守正则吉。受此大福于王母。象征守正不渝，终获尊者之福。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,3,'众允，悔亡。','众人信允，悔恨消亡。象征上进得众心相与，其志上行。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,4,'晋如硕鼠，贞厉。','上进如鼫鼠般贪而畏人，守此则危。象征窃据非位、贪进无德。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,5,'悔亡，失得勿恤，往吉无不利。','悔恨消亡，得失不必忧虑；前往吉，无所不利。象征大明在上，不计得失而往有庆。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(35,6,'晋其角，维用伐邑，厉吉无咎，贞吝。','晋其角，唯用以伐邑；危而吉，无咎，守正亦有憾。象征进之极而施于自治，刚极则不免有憾。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,1,'明夷于飞，垂其翼。 君子于行，三日不食， 有攸往，主人有言。','光明殒伤之时如鸟垂翼而飞。君子远行，三日不食；所往之处，主人有责言。象征见几而作，避祸唯速。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,2,'明夷，夷于左股，用拯马壮，吉。','光明殒伤，伤于左腿，用壮马拯救，吉。象征虽受伤而自救有力，顺以则之。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,3,'明夷于南狩，得其大首，不可疾贞。','于南方田猎，获其首恶；不可急于求正。象征除暗之功成，而化俗宜缓。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,4,'入于左腹，获明夷之心，出于门庭。','进入左腹，获知伤明者的心意，于是出门远去。象征洞悉昏暗之深，决然离去。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,5,'箕子之明夷，利贞。','如箕子之处明夷，利于守正。象征身处至暗而内守其明，晦藏不失其正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(36,6,'不明晦，初登于天，后入于地。','不明而晦暗。初登于天，后坠于地。象征昏暗之极，始照四方而终自取覆亡。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,1,'闲有家，悔亡。','治家于初，防闲有度，悔恨消亡。象征齐家之道贵在防患于始。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,2,'无攸遂，在中馈，贞吉。','无所专遂，主持家中饮食，守正则吉。象征居中守顺，尽其内职。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,3,'家人嗃嗃，悔厉吉﹔妇子嘻嘻，终吝。','治家严厉，家人嗷嗷，虽悔于严厉而吉；妇子嘻嘻无度，终有憾惜。象征家教与其失于宽，宁失于严。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,4,'富家，大吉。','使家富足，大吉。象征以柔顺正位居内，能保其家业。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,5,'王假有家，勿恤吉。','王者以美德感格其家，勿用忧恤，吉。象征以爱相感、以正相交，家道之至。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(37,6,'有孚威如，终吉。','有诚信而威严自重，终吉。象征治家之久，反身自正则人自服。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,1,'悔亡，丧马勿逐，自复﹔见恶人无咎。','悔恨消亡。丧失其马，勿追自返；见恶人，无咎。象征乖离之初不强求，恶人姑且相见以避怨。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,2,'遇主于巷，无咎。','在巷中遇到主人，无咎。象征乖离之时委曲相求，未失其道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,3,'见舆曳，其牛掣，其人天且劓，无初有终。','见车被拖拽，牛被牵制，其人受髡刑割鼻。无初有终。象征始遭众阻，终遇刚阳相合。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,4,'睽孤，遇元夫，交孚，厉无咎。','乖离孤独，遇到刚阳善士，相交以诚，虽危无咎。象征睽孤求合，诚信相辅。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,5,'悔亡，厥宗噬肤，往何咎。','悔恨消亡。其宗亲咬肤般亲密相合，前往有何咎。象征居中应贤，往合有庆。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(38,6,'睽孤， 见豕负涂，载鬼一车， 先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。','乖离孤独，见豕负涂、载鬼一车，先张弓后放下；非寇乃婚媾。往遇阴雨则吉。象征猜疑至极，疑释则群乖化合。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,1,'往蹇，来誉。','前往则遇蹇难，归来则得称誉。象征见险而止，知机之智。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,2,'王臣蹇蹇，匪躬之故。','王臣冒难匡济，蹇之又蹇，非为自身之故。象征尽忠纾难，志在济君而不在身。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,3,'往蹇来反。','前往遇蹇难，归来返居。象征量险而返，内喜其安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,4,'往蹇来连。','前往遇蹇难，归来联合众力。象征独往无功，连类共济。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,5,'大蹇朋来。','大为蹇难之中，朋友来助。象征居尊履险，以中正聚众援。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(39,6,'往蹇来硕，吉；利见大人。','前往遇蹇难，归来则硕大有功，吉；利见大人。象征蹇极而济，从贤共成大事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,1,'无咎。','无咎。象征难既解之初，安静守常即可无失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,2,'田获三狐，得黄矢，贞吉。','田猎获三狐，得黄色箭矢，守正则吉。象征去除谗邪，得中直之道。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,3,'负且乘，致寇至，贞吝。','背负重物又乘车，招致寇至；守此则有憾。象征居非其位、招祸由己。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,4,'解而拇，朋至斯孚。','解去你的拇指之系，朋友至而以诚相交。象征断绝私昵小人，君子方来。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,5,'君子维有解，吉；有孚于小人。','君子有解除之功，吉，并验之于小人之退。象征居尊去恶，小人自退乃见其功。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(40,6,'公用射隼，于高墉之上，获之，无不利。','公在高墉之上射隼，获之，无所不利。象征待机而动，藏器于身，动而不括。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,1,'已事遄往，无咎，酌损之。','祭事既毕速往助上，无咎，斟酌损己之度。象征损己奉上贵在适度。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,2,'利贞，征凶，弗损益之。','利于守正，征往则凶；不自损便是益上。象征守中不妄损，乃真益人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,3,'三人行，则损一人；一人行，则得其友。','三人同行则损一人，一人独行则得其友。象征损有余以致专一，两相疑则不成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,4,'损其疾，使遄有喜，无咎。','减损其疾患，使人速来相助则有喜，无咎。象征自损其不善，从善之速。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,5,'或益之，十朋之龟弗克违，元吉。','或有人赐益十朋之龟，无法辞却，大为吉祥。象征虚中自损者，天人共益之。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(41,6,'弗损益之，无咎，贞吉，利有攸往，得臣无家。','不损己而益人，无咎，守正吉，利有攸往，得臣无家。象征居上以惠下，天下归心。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,1,'利用为大作，元吉，无咎。','利于大有作为，大吉，无咎。象征在下受益，竭力报效方称其益。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,2,'或益之，十朋之龟弗克违，永贞吉。 王用享于帝，吉。','或有人赐益十朋之龟，无法辞却。永守正固则吉。王用享于帝，吉。象征虚中受益，诚通神明。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,3,'益之用凶事，无咎。 有孚中行，告公用圭。','以凶险之事受益，无咎。有诚信行中道，执圭告于公。象征处患难而受益，危中自勉。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,4,'中行，告公从。 利用为依迁国。','行中道而告公必从，利于依附迁国之大事。象征居上下之际，以中道获信而任大事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,5,'有孚惠心，勿问元吉。 有孚惠我德。','有诚信惠心，勿问而大吉；天下以诚信感惠我德。象征至诚惠下，上下交感。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(42,6,'莫益之，或击之，立心勿恒，凶。','无人增益他，或有人攻击他；立心无恒，凶。象征求益无厌、立心不恒，反招其损。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,1,'壮于前趾，往不胜为咎。','强壮于前进的脚趾，往而不胜则为咎。象征恃壮轻进，力不胜任。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,2,'惕号，莫夜有戎，勿恤。','惕惧而呼号，深夜有兵戎亦不必忧。象征危惧自守，有备无患。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,3,'壮于頄，有凶。 君子夬夬，独行遇雨，若濡有愠，无咎。','强壮于颧骨，有凶。君子决然独行，遇雨被濡而有愠色，无咎。象征刚见于色则凶，含忍独断方免咎。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,4,'臀无肤，其行次且。 牵羊悔亡，闻言不信。','臀无肤，行走迟疑。牵羊而行则悔亡，闻言而不信。象征刚而失中，进退失据。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,5,'苋陆夬夬，中行无咎。','如苋陆之柔脆，决而又决，行中道则无咎。象征决去小人当机立断，不失其中。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(43,6,'无号，终有凶。','无可呼号，终有凶。象征小人穷极，终被决去，不可长保。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,1,'系于金柅，贞吉，有攸往，见凶，羸豕孚踟躅。','系于金属车闸，守正则吉；有所往则见凶，瘦弱之猪也会躁动。象征制阴于始，纵之必为患。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,2,'包有鱼，无咎，不利宾。','厨中有鱼，无咎，不利宾客。象征制遇在己，不使旁及于外。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,3,'臀无肤，其行次且，厉，无大咎。','臀无肤，行走迟疑；有危而无大咎。象征处遇不当，行止失据而幸无所遇。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,4,'包无鱼，起凶。','厨中无鱼，起而有凶。象征所遇已失，民心离散之凶。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,5,'以杞包瓜，含章，有陨自天。','以杞树枝叶包瓜，内含章美，自天而降。象征居尊含德，遇之自至。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(44,6,'姤 其角，吝，无咎。','相遇于角，有憾惜，无咎责。象征遇道穷尽，孤高自处而无所遇。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,1,'有孚不终，乃乱乃萃，若号一握为笑，勿恤，往无咎。','有诚信而不能终守，乍乱乍聚；若呼号求应，一握手间转忧为笑。勿恤，往而无咎。象征聚之初心志未定，求正应则安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,2,'引吉，无咎，孚乃利用禴。','受引而聚，吉，无咎；心怀诚信，虽薄祭亦利。象征以诚相聚，不在仪物之丰。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,3,'萃如，嗟如，无攸利，往无咎，小吝。','欲聚而嗟叹，无所利；前往无咎，稍有憾惜。象征所聚不得，求合于上则小憾而无咎。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,4,'大吉，无咎。','大吉方能无咎。象征居上下交聚之际，得众而位不当，唯大善乃免咎。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,5,'萃有位，无咎。 匪孚，元永贞，悔亡。','会聚而居尊位，无咎。有未信服者，永守元正之德则悔亡。象征聚天下者以德不以位。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(45,6,'赍咨涕洟，无咎。','嗟叹流泪，无咎责。象征处聚之极而孤危不安，自伤未得所聚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,1,'允升，大吉。','诚信允合地上升，大为吉祥。象征与上同志，众所推举而升。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,2,'孚乃利用禴，无咎。','心怀诚信，虽薄祭亦利，无咎。象征以诚事上，质素而获通。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,3,'升虚邑。','上升如入无人之邑。象征升进无阻，畅行无疑。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,4,'王用亨于岐山，吉无咎。','王者亨祭于岐山，吉，无咎。象征顺时顺势而升，敬以事上。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,5,'贞吉，升阶。','守正则吉，登阶而升。象征循序渐进、大得其志的升进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(46,6,'冥升，利于不息之贞。','昏冥而仍求升，利于不息地守正。象征升进不知止，唯以正自守可免消亡。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,1,'臀困于株木，入于幽谷，三岁不见。','臀部困于株木之下，进入幽谷，三年不见。象征困之深而自处幽暗不明。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,2,'困于酒食，朱绂方来，利用亨祀，征凶，无咎。','困于酒食，朱绂之贵者方来。利于祭享，征往则凶，无咎责。象征困于丰足，待时以诚自守。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,3,'困于石，据于蒺藜，入于其宫，不见其妻，凶。','困于巨石之下，依凭蒺藜之上；入其宫而不见其妻，凶。象征进退失据，所依非所安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,4,'来徐徐，困于金车，吝，有终。','缓缓而来，困于金车，有憾惜，有终。象征济困之心虽切而力有所牵，终能相合。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,5,'劓刖，困于赤绂，乃徐有说，利用祭祀。','受劓刖之伤，困于赤绂之臣；徐缓自处则有喜悦，利于祭享。象征居尊处困，以中直与诚自通。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(47,6,'困于葛藟，于臲卼，曰动悔。 有悔，征吉。','困于葛藟缠绕、于危脆之地；动则有悔，既悔而征往则吉。象征困极思变，悔而能动则出困。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,1,'井泥不食，旧井无禽。','井底淤泥不可食，废井连禽鸟也不来。象征居下失修、为人所弃。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,2,'井谷射鲋，瓮敝漏。','井底之水只能注射鲋鱼，瓮敝漏水。象征有泉而不上行，德不为人所用。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,3,'井渫不食，为我民恻，可用汲，王明，并受其福。','井已淘净却无人食用，令人心恻；可以汲用，待王之明，则共受其福。象征贤才已备而未遇其时。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,4,'井甃，无咎。','以砖石修治井壁，无咎。象征自治自修，养德待用。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,5,'井冽，寒泉食。','井水清冽，寒泉可食。象征中正之德泽及于人，养而不穷。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(48,6,'井收勿幕，有孚元吉。','井口收功，勿加覆盖；有诚信，大为吉祥。象征博施于民而不私其有，井道大成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,1,'巩用黄牛之革。','用黄牛之革牢牢束缚。象征变革之初，时机未至，固守不动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,2,'巳日乃革之，征吉，无咎。','己日乃可变革，征往吉，无咎。象征时机已至，文明而应，行而有嘉。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,3,'征凶，贞厉，革言三就，有孚。','急于征往则凶，守正防危。变革之言三次合议，方可信从。象征改革须审慎周详，不可躁动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,4,'悔亡，有孚改命，吉。','悔恨消亡，有诚信而改变天命，吉。象征大变革之际，以诚信顺天应人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,5,'大人虎变，未占有孚。','大人之变如虎纹焕然，未占而有诚信。象征圣贤变革，文理炳著，天下自信。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(49,6,'君子豹变，小人革面，征凶，居贞吉。','君子之变如豹纹蔚然，小人则革面相从。征往则凶，安居守正则吉。象征变革既成，宜安定守成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,1,'鼎颠趾，利出否，得妾以其子，无咎。','鼎颠覆其足，利于倒出秽物；得妾以生子，无咎。象征因败致用、去故纳新。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,2,'鼎有实，我仇有疾，不我能即，吉。','鼎中有实，我的仇怨者有疾不能近我，吉。象征自守充实，谨其所往则人莫能害。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,3,'鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。','鼎耳变异，行动受阻，肥美雉膏不得食用；待阴阳和雨，悔亏终吉。象征才实而失其提挈，待时乃通。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,4,'鼎折足，覆公𫗧，其形渥，凶。','鼎足折断，倾覆公侯之美食，鼎身沾濡，凶。象征力小任重、不堪其事而败。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,5,'鼎黄耳金铉，利贞。','鼎配黄耳金铉，利于守正。象征中位虚己，得贤为辅。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(50,6,'鼎玉铉，大吉，无不利。','鼎配玉铉，大吉，无所不利。象征刚柔相济、调和至极，养贤功成。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,1,'震来虩虩，后笑言哑哑，吉。','震来时惶恐戒惧，其后笑语自如，吉。象征因惧而修，由恐致福。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,2,'震来厉，亿丧贝，跻于九陵，勿逐，七日得。','震来有危，料想丧失财货，登于九陵；勿逐，七日自得。象征遇险舍物避害，失者终复。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,3,'震苏苏，震行无眚。','震动不安的样子，因震惧而行则无灾患。象征不当位而知惧，惧而能行可免眚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,4,'震遂泥。','震动而后陷于泥中。象征刚陷于柔、震道不光，惊惧而不能自拔。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,5,'震往来厉，亿无丧，有事。','震来上下往来皆危，审度而行，所守之事不失。象征危行其中，守其大者。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(51,6,'震索索，视矍矍，征凶。 震不于其躬，于其邻，无咎。 婚媾有言。','震之极，惶惶四顾，征往则凶。震不及己身而及其邻，先戒则无咎；婚媾有言。象征见邻知戒、未雨绸缪。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,1,'艮其趾，无咎，利永贞。','抑止在脚趾，无咎，利于永守正固。象征止于事初，未失其正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,2,'艮其腓，不拯其随，其心不快。','抑止在小腿，不能救助所随之主，心中不快。象征受制随人、不得自主之憾。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,3,'艮其限，列其夤，厉薰心。','抑止在腰部，撕裂脊肉，危厉熏心。象征强止其不可止，上下隔绝之危。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,4,'艮其身，无咎。','抑止其身，无咎。象征止于自身本分，不妄动妄求。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,5,'艮其辅，言有序，悔亡。','抑止在口，言语有序，悔恨消亡。象征谨言有节，慎其所出。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(52,6,'敦艮，吉。','敦厚地抑止，吉。象征止道之成，安静笃实而有终。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,1,'鸿渐于干，小子厉，有言，无咎。','鸿雁渐进于水涯。小子有危，受些非议，无咎。象征始进于下，虽危而义不可咎。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,2,'鸿渐于磐，饮食衎衎，吉。','鸿雁渐进于磐石，饮食和乐，吉。象征进而得安，与人共享其乐。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,3,'鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。','鸿雁渐进于陆地。夫征不复，妇孕不育，凶；利于抵御寇害。象征冒进失序、离群失类之凶。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,4,'鸿渐于木，或得其桷，无咎。','鸿雁渐进于树木，或得平柯而栖，无咎。象征以柔巽自处，虽非其位而得所安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,5,'鸿渐于陵，妇三岁不孕，终莫之胜，吉。','鸿雁渐进于高陵。妇三年不孕，但终莫之胜，吉。象征中正相应，虽久受阻隔而愿终得遂。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(53,6,'鸿渐于逵，其羽可用为仪，吉。','鸿雁渐进于云路，其羽可用作仪饰，吉。象征功成身退、进退有序，其德可为仪范。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,1,'归妹以娣，跛能履，征吉。','以娣妾随嫁，如跛者能履，征往吉。象征位卑而安其分，恒守自处。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,2,'眇能视，利幽人之贞。','如眇者能视，利于幽静者守正。象征所托非良而不改其操，幽贞自守。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,3,'归妹以须，反归以娣。','以待嫁之身求归，反而归为娣妾。象征求配失礼，自降其身。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,4,'归妹愆期，迟归有时。','嫁期延误，迟归有时。象征宁可待时，不轻易委身。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,5,'帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。','帝乙嫁妹，正夫人之衣袖不如娣妾华美；月近望则吉。象征尊贵而尚礼不尚饰，谦中之德。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(54,6,'女承筐无实，士刲羊无血，无攸利。','女子捧筐而无实物，士人刲羊而无血。无所利。象征虚应故事、夫妇之道有名无实。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,1,'遇其配主，虽旬无咎，往有尚。','遇其匹配之主，虽旬日均等而无咎，前往有尚。象征明动相资，配合得宜。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,2,'丰其蔀，日中见斗，往得疑疾，有孚发若，吉。','丰大其遮蔽，日中而见斗星。前往得疑疾；以诚信发其志意，吉。象征明被遮蔽，唯以至诚感悟其上。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,3,'丰其沛，日中见昧，折其右肱，无咎。','丰大其帷幔，日中而见小星；折其右肱，无咎责。象征遮蔽至深、辅弼已折，不可大事。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,4,'丰其蔀，日中见斗，遇其夷主，吉。','丰大其遮蔽，日中见斗；遇其同德之主，吉。象征幽暗之中遇明相济。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,5,'来章，有庆誉，吉。','招来天下章美之才，有庆誉，吉。象征虚己来贤，共成丰大之治。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(55,6,'丰其屋，蔀其家，窥其户，阒其无人，三岁不见，凶。','丰大其屋而自蔽其家，窥其户阒然无人，三年不见，凶。象征自高自蔽、丰极而自绝于人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,1,'旅琐琐，斯其所取灾。','行旅猥琐细碎，这是自取其灾。象征处旅卑微而志穷，自招其辱。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,2,'旅即次，怀其资，得童仆贞。','行旅安顿于客舍，怀藏资财，得童仆之忠贞。象征旅中得安、内外皆备。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,3,'旅焚其次，丧其童仆，贞厉。','行旅焚其客舍，丧其童仆之贞，危。象征过刚自高，旅中失其所安与所辅。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,4,'旅于处，得其资斧，我心不快。','行旅暂处一地，得资斧，我心不快。象征虽有所获而非其位，心终未安。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,5,'射雉一矢亡，终以誉命。','射雉，一箭而亡之，终以誉命。象征以文明柔中处旅，虽小失而终获荣命。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(56,6,'鸟焚其巢，旅人先笑后号啕。 丧牛于易，凶。','鸟焚其巢，旅人先笑后号啕；轻易失牛，凶。象征处旅而骄、高亢自焚之祸。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,1,'进退，利武人之贞。','进退迟疑，利于武人之贞。象征过于卑巽则志疑，济之以果决。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,2,'巽在床下，用史巫纷若，吉无咎。','卑顺于床下，用史巫纷然祈告，吉，无咎。象征谦卑至诚、自通于幽明而不为谄。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,3,'频巽，吝。','频繁而勉强地卑顺，有憾惜。象征非出本心之顺，志穷而屡失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,4,'悔亡，田获三品。','悔恨消亡，田猎获三品之物。象征以柔行权、上下兼济而有功。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,5,'贞吉悔亡，无不利。 无初有终，先庚三日，后庚三日，吉。','守正则吉，悔亡，无所不利；无初有终。先庚三日，后庚三日，吉。象征申命改作、慎始虑终。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(57,6,'巽在床下，丧其资斧，贞凶。','卑顺于床下，丧其资斧，守此则凶。象征巽极失断，自失其刚则穷。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,1,'和兑，吉。','平和之悦，吉。象征不偏不私、和而不流的喜悦。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,2,'孚兑，吉，悔亡。','诚信之悦，吉，悔恨消亡。象征以诚立悦，不为邪媚所动。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,3,'来兑，凶。','前来求悦，凶。象征屈己媚人以求欢悦，悦不由正道而来。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,4,'商兑，未宁，介疾有喜。','商度其悦而心未安宁，绝其疾恶则有喜。象征择善而悦，去邪存正。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,5,'孚于剥，有厉。','信任剥削阳刚的小人，有危厉。象征尊位轻信谄佞，当位而须自警。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(58,6,'引兑。','引诱他人同悦。象征悦之极而引人入己，悦道已偏。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,1,'用拯马壮，吉。','用强壮之马拯救涣散，吉。象征散之初拯之尚易，得力则顺。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,2,'涣奔其机，悔亡。','涣散之时奔就几案之安，悔恨消亡。象征危中得所依凭，遂其安愿。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,3,'涣其躬，无悔。','涣散其私身，无悔。象征忘私济难，志在向外成务。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,4,'涣其群，元吉。 涣有丘，匪夷所思。','涣散其朋党，大为吉祥；涣散而又聚合如丘，非常人所能思及。象征破小群而成大群，公而忘私。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,5,'涣汗其大号，涣王居，无咎。','涣散之时发布大号令如汗之周浃，散王之积聚以聚人心，无咎。象征居尊济涣，正位施惠。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(59,6,'涣其血，去逖出，无咎。','涣散其血伤，远离忧惧而出，无咎。象征远害避患，涣道之终得全。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,1,'不出户庭，无咎。','不出户庭，无咎。象征知通塞之时，慎守而不妄出。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,2,'不出门庭，凶。','不出门庭，凶。象征当行而不行，失时之极。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,3,'不节若，则嗟若，无咎。','不知节制，则又嗟叹，无人可咎。象征失节自致忧悔，咎由自取。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,4,'安节，亨。','安然行节，亨通。象征顺承上道、安于节制而不勉强。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,5,'甘节，吉﹔往有尚。','甘美的节制，吉，前往有尚。象征居中得正、节而能甘，人皆乐从。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(60,6,'苦节，贞凶，悔亡。','苦涩的节制，守此则凶，悔恨自消。象征节制过苦不可常行，知其不可而悔则免咎。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,1,'虞吉，有他不燕。','安守诚信则吉，别有他求则不安。象征信贵专一，虞度而后定则不迁。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,2,'鸣鹤在阴，其子和之，我有好爵，吾与尔靡之。','鹤鸣于树荫之下，其子和之；我有好爵，与你共享。象征至诚相感，同气相应。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,3,'得敌，或鼓或罢，或泣或歌。','得遇相敌者，或鼓或止，或泣或歌。象征信系于人而不由己，喜怒失常。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,4,'月几望，马匹亡，无咎。','月近望之时，马匹亡失其偶，无咎。象征绝类从上、专一其信。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,5,'有孚挛如，无咎。','心怀诚信而维系天下，无咎。象征居尊位以至诚相挽结，信之主也。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(61,6,'翰音登于天，贞凶。','鸡鸣之声欲登于天，守此则凶。象征虚声无实、信不副名，何可长久。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,1,'飞鸟以凶。','飞鸟逆势上翔，凶。象征上飞失所，过之不当，灾不可救。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,2,'过其祖，遇其妣；不及其君，遇其臣；无咎。','过其祖而遇其妣；不及其君而遇其臣，无咎。象征过而不越其分，守臣节而得中。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,3,'弗过防之，从或戕之，凶。','不肯过为防备，随之而来者或加伤害，凶。象征恃刚不备，祸由轻忽。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,4,'无咎，弗过遇之。 往厉必戒，勿用永贞。','无咎，不过分而与之相遇；前往有危必须戒惧，勿恒用其刚。象征以刚处柔、戒慎不终日恃。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,5,'密云不雨，自我西郊，公弋取彼在穴。','密云不雨，自我西郊；公以弋绳取彼在穴之物。象征阴居尊位、德薄而求助于下。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(62,6,'弗遇过之，飞鸟离之，凶，是谓灾眚。','不与之遇而过分高飞，飞鸟远离，凶，是谓灾殃。象征过之极、亢而无应，自取灾眚。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,1,'曳其轮，濡其尾，无咎。','拖住车轮，沾湿尾部，无咎。象征济成之初仍持稳缓，不冒进则无失。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,2,'妇丧其茀，勿逐，七日得。','妇人丧失车蔽，勿逐，七日自得。象征暂失所凭而中道自守，失者终复。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,3,'高宗伐鬼方，三年克之，小人勿用。','高宗伐鬼方，三年乃克；小人勿用。象征成业之艰，胜后尤戒小人。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,4,'𦈡有衣袽，终日戒。','船有渗漏备有絮塞，终日戒惧。象征居安虑患，备豫不虞。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,5,'东邻杀牛，不如西邻之禴祭，实受其福。','东邻杀牛盛祭，不如西邻薄祭之实受其福。象征祭祀贵诚不贵丰，时义重于仪文。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(63,6,'濡其首，厉。','沾湿其首，危。象征既济之终犹涉险不止，安极忘危之厉。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,1,'濡其尾，吝。','沾湿其尾，有憾惜。象征力不足而急于求济，不知量力。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,2,'曳其轮，贞吉。','拖住车轮，守正则吉。象征以刚居中、自制待时，不急于进。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,3,'未济，征凶，利涉大川。','未济之时征往则凶，利于涉越大川。象征时机将至而力未充，须借势众力以济。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,4,'贞吉，悔亡，震用伐鬼方，三年有赏于大国。','守正则吉，悔恨消亡。奋发振动以伐鬼方，三年而受赏于大国。象征济难有志，久而有功。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,5,'贞吉，无悔，君子之光，有孚，吉。','守正则吉，无悔；君子之光辉有诚信，吉。象征柔中居尊，其明而信，将济之主。');
INSERT INTO yao_text(hexagram_id,line_position,yao_ci,annotation) VALUES(64,6,'有孚于饮酒，无咎，濡其首，有孚失是。','心怀诚信而宴饮，无咎；沾湿其首，则有诚信亦失其度。象征乐天知命可也，纵乐忘形则失节。');
