BEGIN;
DELETE FROM yao_text;
UPDATE hexagram SET gua_ci='元，亨，利，贞。', gua_annotation='乾为纯阳之卦，象征天与刚健。卦辞四字古称四德：元为开端，亨为通达，利为适宜，贞为正固。象征事物生机充沛、自强不息的状态。', version=version+1 WHERE id=1;
UPDATE hexagram SET gua_ci='坤，元，亨，利牝马之贞。君子有攸往，先迷后得主，利西南得朋，东北丧朋。 安贞，吉。', gua_annotation='坤为纯阴之卦，象征地与柔顺。以牝马喻其德：柔顺而行地无疆。强调厚德载物、顺势而为，先迷后得，安于正固。', version=version+1 WHERE id=2;
UPDATE hexagram SET gua_ci='元，亨，利，贞，勿用，有攸往，利建侯。', gua_annotation='屯象征初生与艰难。万物始生，充满生机又步履维艰。宜守正固本，培植根基，不宜轻举妄动，利于建立辅助力量。', version=version+1 WHERE id=3;
UPDATE hexagram SET gua_ci='亨。 匪我求童蒙，童蒙求我。 初噬告，再三渎，渎则不告。利贞。', gua_annotation='蒙象征蒙昧与启蒙。不是我求童蒙，而是童蒙求我；初次诚心问筮则告，再三轻渎则不告。强调教育贵在诚敬主动。', version=version+1 WHERE id=4;
UPDATE hexagram SET gua_ci='有孚，光亨，贞吉。 利涉大川。', gua_annotation='需象征等待。心怀诚信则光明亨通，守正则吉，利于涉越大川。强调时机未至时的涵养与守候，待时而动。', version=version+1 WHERE id=5;
UPDATE hexagram SET gua_ci='有孚，窒。 惕中吉。 终凶。 利见大人，不利涉大川。', gua_annotation='讼象征争讼。心有诚信而遭窒塞，惕惧而中止则吉，争讼到底则凶。利于见大人决断，不利于涉险冒进。', version=version+1 WHERE id=6;
UPDATE hexagram SET gua_ci='贞，丈人，吉无咎。', gua_annotation='师象征兵众与统率。守持正固，以刚中长者为帅则吉而无咎。强调兴师动众须出于正道、用人得当。', version=version+1 WHERE id=7;
UPDATE hexagram SET gua_ci='吉。 原筮元永贞，无咎。 不宁方来，后夫凶。', gua_annotation='比象征亲附与团结。吉。推原占问，长久守正则无咎。不安宁者纷纷来附，迟迟不至者有凶。强调亲比贵在及时与诚正。', version=version+1 WHERE id=8;
UPDATE hexagram SET gua_ci='亨。 密云不雨，自我西郊。', gua_annotation='小畜象征小有积蓄、以小畜大。亨通。密云不雨，自我西郊。象征力量尚薄，阴方畜阳，事将成而未成之际。', version=version+1 WHERE id=9;
UPDATE hexagram SET gua_ci='履虎尾，不咥人，亨。', gua_annotation='履象征践履与循礼而行。踩到虎尾，虎不咬人，亨通。象征以和悦谨慎之态行于危险之侧，礼可化险。', version=version+1 WHERE id=10;
UPDATE hexagram SET gua_ci='小往大来，吉亨。', gua_annotation='泰象征通泰。小者往而大者来，吉而亨通。天地之气交合，上下之情交通，万物各遂其生，是安泰之世的气象。', version=version+1 WHERE id=11;
UPDATE hexagram SET gua_ci='否之匪人，不利君子贞，大往小来。', gua_annotation='否象征闭塞。否之非人道，不利君子守正，大者往而小者来。天地不交、上下隔绝之世，君子宜俭德避难。', version=version+1 WHERE id=12;
UPDATE hexagram SET gua_ci='同人于野，亨。 利涉大川，利君子贞。', gua_annotation='同人象征和同于人。于旷野与人和同，亨通，利于涉越大川，利于君子守正。强调大公无私方能聚合众力。', version=version+1 WHERE id=13;
UPDATE hexagram SET gua_ci='元亨。', gua_annotation='大有象征大有所获、所有者大。元亨。如日丽中天，明照万物。强调盛大丰有之时须顺天而行、谦以处之。', version=version+1 WHERE id=14;
UPDATE hexagram SET gua_ci='亨，君子有终。', gua_annotation='谦象征谦虚。亨通，君子有好的结局。地中有山，内蕴崇高而外形卑下。谦是诸德之柄，唯谦受益。', version=version+1 WHERE id=15;
UPDATE hexagram SET gua_ci='利建侯行师。', gua_annotation='豫象征欢乐安和。利于建侯行师。顺其性而动，故天地如之。强调乐而有节、顺动而不溺于逸乐。', version=version+1 WHERE id=16;
UPDATE hexagram SET gua_ci='元亨利贞，无咎。', gua_annotation='随象征随从与随和。元亨利贞，无咎。强调随时而动、随善而从；唯随之以正，方能亨通无失。', version=version+1 WHERE id=17;
UPDATE hexagram SET gua_ci='元亨，利涉大川。 先甲三日，后甲三日。', gua_annotation='蛊象征积弊与整治。元亨，利涉大川。先甲三日，后甲三日。器久不用而虫生，事久因循而弊起；治蛊须慎始虑终。', version=version+1 WHERE id=18;
UPDATE hexagram SET gua_ci='元，亨，利，贞。 至于八月有凶。', gua_annotation='临象征居上临下、督导亲临。元亨利贞。至于八月有凶。阳气方长，盛而须防衰；临人以德，教思无穷。', version=version+1 WHERE id=19;
UPDATE hexagram SET gua_ci='盥而不荐，有孚颙若。', gua_annotation='观象征观仰与观察。祭前洁手而未献祭品之时，诚敬之心充盈可仰。强调以中正示人，以诚敬观天下。', version=version+1 WHERE id=20;
UPDATE hexagram SET gua_ci='亨。 利用狱。', gua_annotation='噬嗑象征咬合与刑罚。亨通，利于用狱。物有梗阻，咬而合之；治道遇梗，明罚敕法以去之。', version=version+1 WHERE id=21;
UPDATE hexagram SET gua_ci='亨。 小利有所往。', gua_annotation='贲象征文饰。亨通，柔来文刚，小利有所往。强调文饰以质为本，文质彬彬而不尚虚华。', version=version+1 WHERE id=22;
UPDATE hexagram SET gua_ci='不利有攸往。', gua_annotation='剥象征剥落侵蚀。不利有所往。阴长阳消，小人渐盛之时；君子顺时而止，厚下以安宅。', version=version+1 WHERE id=23;
UPDATE hexagram SET gua_ci='亨。 出入无疾，朋来无咎。 反复其道，七日来复，利有攸往。', gua_annotation='复象征回复、复归。亨通。出入无疾，朋来无咎，七日来复，利有攸往。一阳来复，天地生机重见。', version=version+1 WHERE id=24;
UPDATE hexagram SET gua_ci='元，亨，利，贞。 其匪正有眚，不利有攸往。', gua_annotation='无妄象征不妄为、合于天道。元亨利贞。其匪正有眚，不利有攸往。动以天理则亨，妄动则有灾。', version=version+1 WHERE id=25;
UPDATE hexagram SET gua_ci='利贞，不家食吉，利涉大川。', gua_annotation='大畜象征大为蓄聚、以刚畜健。利贞。不家食吉，利涉大川。蓄德养贤，畜极则通，可任大事。', version=version+1 WHERE id=26;
UPDATE hexagram SET gua_ci='贞吉。观颐，自求口实。', gua_annotation='颐象征颐养。守正则吉。观察所养之人与自养之道。养身养德、养人养于人，皆以正为本。', version=version+1 WHERE id=27;
UPDATE hexagram SET gua_ci='栋桡，利有攸往，亨。', gua_annotation='大过象征大为过越、非常之时。栋梁弯曲，利有攸往，亨。本末俱弱而中强，非常之事须非常之才德。', version=version+1 WHERE id=28;
UPDATE hexagram SET gua_ci='习坎，有孚，维心亨，行有尚。', gua_annotation='坎象征重重险陷。有诚信，维系其心则亨通，行动必有功。习险而不失其信，方能出险。', version=version+1 WHERE id=29;
UPDATE hexagram SET gua_ci='利贞，亨。 畜牝牛，吉。', gua_annotation='离象征附丽与光明。利贞，亨。畜养牝牛则吉。日月丽天、百谷丽土；柔顺而附于中正，则化成天下。', version=version+1 WHERE id=30;
UPDATE hexagram SET gua_ci='亨，利贞，取女吉。', gua_annotation='咸象征交感。亨通，利于守正，娶女则吉。山上有泽，二气感应以相与；天地感而万物生。', version=version+1 WHERE id=31;
UPDATE hexagram SET gua_ci='亨，无咎，利贞，利有攸往。', gua_annotation='恒象征恒久。亨通，无咎，利贞，利有攸往。雷风相与，刚柔皆应；观其所恒，而天地万物之情可见。', version=version+1 WHERE id=32;
UPDATE hexagram SET gua_ci='亨，小利贞。', gua_annotation='遁象征退避。亨通，小利于守正。阴渐长而阳宜退；君子远小人，不恶而严，退以全其道。', version=version+1 WHERE id=33;
UPDATE hexagram SET gua_ci='利贞。', gua_annotation='大壮象征大为强盛。利于守正。雷在天上，刚以动，故壮。强盛之时尤须非礼弗履，壮而合正方可久。', version=version+1 WHERE id=34;
UPDATE hexagram SET gua_ci='康侯用锡马蕃庶，昼日三接。', gua_annotation='晋象征晋升、上进。康侯受赐众马，一日之内三次接见。明出地上，柔进而上行，以德受宠之象。', version=version+1 WHERE id=35;
UPDATE hexagram SET gua_ci='利艰贞。', gua_annotation='明夷象征光明殒伤。利于艰难中守正。明入地中，昏暗在上；君子用晦而明，内文明而外柔顺以蒙大难。', version=version+1 WHERE id=36;
UPDATE hexagram SET gua_ci='利女贞。', gua_annotation='家人象征一家之人。利于女子守正。女正位乎内，男正位乎外；正家而天下定。', version=version+1 WHERE id=37;
UPDATE hexagram SET gua_ci='小事吉。', gua_annotation='睽象征乖背违离。小事吉。火动而上，泽动而下；二女同居而志不同行。睽而求同，异中有合。', version=version+1 WHERE id=38;
UPDATE hexagram SET gua_ci='利西南，不利东北；利见大人，贞吉。', gua_annotation='蹇象征艰难险阻。利西南，不利东北；利见大人，守正则吉。见险而能止，知矣；处蹇宜反身修德。', version=version+1 WHERE id=39;
UPDATE hexagram SET gua_ci='利西南，无所往，其来复吉。 有攸往，夙吉。', gua_annotation='解象征解除舒缓。利西南。无所往则来复吉，有攸往则夙吉。雷雨作而百果草木皆甲坼，险难解散之时。', version=version+1 WHERE id=40;
UPDATE hexagram SET gua_ci='有孚，元吉，无咎，可贞，利有攸往。曷之用，二簋可用享。', gua_annotation='损象征减损。有诚信，大吉，无咎，可守正，利有攸往。损下益上、损刚益柔皆须有时；损而有孚则吉。', version=version+1 WHERE id=41;
UPDATE hexagram SET gua_ci='利有攸往，利涉大川。', gua_annotation='益象征增益。利有攸往，利涉大川。损上益下，民说无疆；其道与时偕行。', version=version+1 WHERE id=42;
UPDATE hexagram SET gua_ci='扬于王庭，孚号，有厉，告自邑，不利即戎，利有攸往。', gua_annotation='夬象征决断、决去。扬于王庭，以诚呼号，有危厉。告自邑，不利即戎，利有攸往。五阳决一阴，决而能和。', version=version+1 WHERE id=43;
UPDATE hexagram SET gua_ci='女壮，勿用取女。', gua_annotation='姤象征相遇。女子强壮，勿娶此女。一阴始生而遇五阳；遇之不正，不可与长。防微杜渐之卦。', version=version+1 WHERE id=44;
UPDATE hexagram SET gua_ci='亨。 王假有庙，利见大人，亨，利贞。 用大牲吉，利有攸往。', gua_annotation='萃象征会聚。亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。聚以正道，观其所聚而天地万物之情可见。', version=version+1 WHERE id=45;
UPDATE hexagram SET gua_ci='元亨，用见大人，勿恤，南征吉。', gua_annotation='升象征上升。元亨。用见大人，勿恤，南征吉。地中生木，柔以时升；积小以高大。', version=version+1 WHERE id=46;
UPDATE hexagram SET gua_ci='亨，贞，大人吉，无咎，有言不信。', gua_annotation='困象征困穷。亨。守正，大人吉，无咎。有言不信。泽中无水之象；困而不失其所亨，唯君子能之。', version=version+1 WHERE id=47;
UPDATE hexagram SET gua_ci='改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。', gua_annotation='井象征水井、养而不穷。改邑不改井，无丧无得，往来井井。汲至井口而未出，毁其瓶则凶。德惠常施而有终。', version=version+1 WHERE id=48;
UPDATE hexagram SET gua_ci='巳日乃孚，元亨利贞，悔亡。', gua_annotation='革象征变革。己日乃孚，元亨利贞，悔亡。水火相息，其变乃成；顺天应人，革之时义大矣。', version=version+1 WHERE id=49;
UPDATE hexagram SET gua_ci='元吉，亨。', gua_annotation='鼎象征鼎器、化生为熟。元吉，亨。以木巽火，烹饪以养人；正位凝命，养贤之卦。', version=version+1 WHERE id=50;
UPDATE hexagram SET gua_ci='亨。 震来虩虩，笑言哑哑。 震惊百里，不丧匕鬯。', gua_annotation='震象征雷动与震惧。亨。震来虩虩，笑言哑哑；震惊百里，不丧匕鬯。恐惧修省，临变不乱。', version=version+1 WHERE id=51;
UPDATE hexagram SET gua_ci='艮其背，不获其身，行其庭，不见其人，无咎。', gua_annotation='艮象征抑止、静止。艮其背，不获其身；行其庭，不见其人，无咎。时止则止，时行则行，动静不失其时。', version=version+1 WHERE id=52;
UPDATE hexagram SET gua_ci='女归吉，利贞。', gua_annotation='渐象征渐进。女归吉，利贞。山上有木，其进以渐；进得位、动不穷，循序之道。', version=version+1 WHERE id=53;
UPDATE hexagram SET gua_ci='征凶，无攸利。', gua_annotation='归妹象征嫁女。征凶，无攸利。说以动，所归者妹；天地之大义而失其位，戒于躁动失正。', version=version+1 WHERE id=54;
UPDATE hexagram SET gua_ci='亨，王假之，勿忧，宜日中。', gua_annotation='丰象征丰大。亨，王假之；勿忧，宜日中。明以动，盛大之时；日中则昃，月盈则食，盛极须防衰。', version=version+1 WHERE id=55;
UPDATE hexagram SET gua_ci='小亨，旅贞吉。', gua_annotation='旅象征行旅、羁旅在外。小亨，旅贞吉。山上有火，过而不留；旅之时柔得中乎外而顺乎刚。', version=version+1 WHERE id=56;
UPDATE hexagram SET gua_ci='小亨，利攸往，利见大人。', gua_annotation='巽象征顺入、谦逊。小亨，利有攸往，利见大人。随风相继，申命行事；柔皆顺乎刚，巽以行权。', version=version+1 WHERE id=57;
UPDATE hexagram SET gua_ci='亨，利贞。', gua_annotation='兑象征喜悦。亨，利贞。丽泽相滋，朋友讲习；说以先民，民忘其劳。悦而能正，方为真悦。', version=version+1 WHERE id=58;
UPDATE hexagram SET gua_ci='亨。 王假有庙，利涉大川，利贞。', gua_annotation='涣象征涣散、又济散聚合。亨，王假有庙，利涉大川，利贞。风行水上，离披解散；圣王以享祭聚合人心。', version=version+1 WHERE id=59;
UPDATE hexagram SET gua_ci='亨。 苦节不可贞。', gua_annotation='节象征节制。亨。苦节不可贞。泽上有水，其容有限；节以制度，不伤财不害民，节贵适中。', version=version+1 WHERE id=60;
UPDATE hexagram SET gua_ci='豚鱼吉，利涉大川，利贞。', gua_annotation='中孚象征心中诚信。豚鱼吉，利涉大川，利贞。泽上有风，感于水中；诚信至而豚鱼亦感，乃可化邦。', version=version+1 WHERE id=61;
UPDATE hexagram SET gua_ci='亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。', gua_annotation='小过象征小有过越。亨，利贞。可小事，不可大事。飞鸟遗音，不宜上宜下，大吉。过以就正、矫枉适中之时。', version=version+1 WHERE id=62;
UPDATE hexagram SET gua_ci='亨，小利贞，初吉终乱。', gua_annotation='既济象征事已成。亨小，利贞；初吉终乱。水火相交，各得其用；既成之时，唯思患而豫防之。', version=version+1 WHERE id=63;
UPDATE hexagram SET gua_ci='亨，小狐汔济，濡其尾，无攸利。', gua_annotation='未济象征事未成。亨。小狐汔济，濡其尾，无攸利。火在水上，不相为用；未济之时蕴含将济之机，慎辨而行。', version=version+1 WHERE id=64;
COMMIT;